import type { MetadataRoute } from 'next';
import { site } from '@/lib/site';

/**
 * Crawl rules.
 *
 * ── Why /api/og is explicitly allowed ─────────────────────────────────────
 * Every Open Graph and Twitter card image on this site is generated by
 * `/api/og`. A blanket `Disallow: /api/` therefore blocked the site's own
 * social preview images: Twitterbot and several link-preview fetchers honour
 * robots.txt before fetching an image, so shared links rendered without a
 * card. The allow rule is listed BEFORE the disallow because that is the
 * order most crawlers read, and the more specific path wins regardless.
 *
 * Everything else under /api stays closed — /api/contact is a write endpoint
 * with no business being crawled.
 */

const RULE = {
  allow: ['/', '/api/og'],
  disallow: ['/api/'],
} as const;

/*
 * Search and answer-engine agents: these fetch pages to cite them in an
 * answer, or on a user's behalf. Allowing them is what makes the site
 * citable in ChatGPT search, Claude, Perplexity, Copilot (via Bing), Apple
 * and Gemini (Google-Extended governs Gemini grounding/training use).
 * Oct 29 2026: Claude-SearchBot, Claude-User, Perplexity-User, Bingbot and
 * Applebot added — they were covered by `*` but not named.
 */
const AI_SEARCH_CRAWLERS = [
  'OAI-SearchBot',
  'ChatGPT-User',
  'Claude-SearchBot',
  'Claude-User',
  'PerplexityBot',
  'Perplexity-User',
  'Google-Extended',
  'GoogleOther',
  'Bingbot',
  'Applebot',
  'DuckAssistBot',
  'Amazonbot',
];

/*
 * Model-training crawlers. Currently allowed. An earlier note said to block
 * training-only crawlers; that is pending Erekle's decision — do not change
 * this list without it.
 */
const AI_TRAINING_CRAWLERS = [
  'GPTBot',
  'ClaudeBot',
  'anthropic-ai',
  'CCBot',
  'Bytespider',
  'Applebot-Extended',
];

const AI_CRAWLERS = [...AI_SEARCH_CRAWLERS, ...AI_TRAINING_CRAWLERS];

export default function robots(): MetadataRoute.Robots {
  return {
    rules: [
      { userAgent: '*', allow: [...RULE.allow], disallow: [...RULE.disallow] },
      // Explicitly allow the major answer-engine and AI search crawlers while
      // keeping private/server endpoints out of the crawl surface.
      ...AI_CRAWLERS.map((userAgent) => ({
        userAgent,
        allow: [...RULE.allow],
        disallow: [...RULE.disallow],
      })),
    ],
    sitemap: `${site.url}/sitemap.xml`,
    host: site.url,
  };
}
